def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    citations = []
    for _ in range(n):
        citations.append(int(next(iterator)))

    citations.sort(reverse=True)

    h_index = 0
