        # So the candidate h_index is min(i+1, citations[i])
        # But we are iterating from highest, so the first time citations[i] < i+1, we stop.
        # The h_index is the count of papers where citations[i] >= i+1.
        if c >= i + 1:
            h_index = i + 1
        else:
            break

    print(h_index)

